def summarize_rank_attribute_groups(items) -> dict:
    """Summarize rank-attribute comparisons across named groups.

    ``items`` must be a list of at least two mappings, each with exactly
    the keys ``name, comparison`` in that order.  ``name`` is a unique
    non-empty str and ``comparison`` is a complete
    :func:`compare_batch_rank_attribute` result (schema
