                if total == 0:
                    contribution = None
                    uncertainty = None
                else:
                    contribution = _round_output(
                        sum(n * c for n, c, _u in retained) / total
                    )
                    uncertainty = _round_output(
                        math.sqrt(sum((n * u) ** 2 for n, _c, u in retained))
                        / total
                    )
                result_data.append(
                    {
                        "scenario": scenario,
                        "element": element,
                        "driver": driver,
                        "group_count": group_count,
                        "count": total,
                        "contribution": contribution,
                        "uncertainty": uncertainty,
                    }
                )

    return {
        "schema": _RANK_ATTRIBUTE_GROUP_SUMMARY_SCHEMA,
        "groups": names,
        "scenarios": list(first_scenarios),
        "elements": list(first_elements),
        "drivers": list(first_drivers),
        "data": result_data,
    }

